289: bool CDirectorAI::issueMove()
290: {
291: 	// Hard cap per turn so a stuck target can never turn into an unbounded loop.
292: 	if(movesThisTurn >= MAX_MOVES_PER_TURN)
293: 	{
294: 		logGlobal->info("DirectorAI: move budget for this turn exhausted (%d)", movesThisTurn);
295: 		return false;
296: 	}
297: 
298: 	std::vector<const CGHeroInstance *> heroes = cb->getHeroesInfo();
299: 	const CGHeroInstance * hero = pickHero(heroes);
300: 	if(!hero)
301: 	{
302: 		logGlobal->info("DirectorAI: no hero with movement points");
303: 		return false;
304: 	}
305: 
306: 	int3 destination(-1, -1, -1);
307: 	std::string reason;
308: 	if(!findTarget(hero, destination, reason))
309: 	{
310: 		logGlobal->info("DirectorAI: no target for hero %d", hero->id.getNum());
311: 		blockedHeroes.insert(hero->id.getNum());
312: 		return issueMove();
313: 	}
314: 
315: 	const int3 here = hero->visitablePos();
316: 	int3 step = destination;
317: 	bool zeroLength = false;
318: 
319: 	if(here == destination)
320: 	{
321: 		// A zero-length move is the legal way to visit / fight the object standing on the
322: 		// current tile (this is what Nullkiller2 does too). It is not a failure.
323: 		zeroLength = true;
324: 	}
325: 	else
326: 	{
327: 		CGPath path;
328: 		pathfinder->invalidatePaths();
329: 		pathfinder->getPathsInfo(hero)->getPath(path, destination);
