332: 			logGlobal->info("DirectorAI: hero %d cannot reach %s reason=%s",
333: 				hero->id.getNum(), destination.toString(), reason);
334: 			return false;
335: 		}
336: 		const CGPathNode next = path.nextNode();
337: 		if(next.turns != 0)
338: 		{
339: 			logGlobal->info("DirectorAI: %s not reachable this turn (turns=%d) reason=%s",
340: 				destination.toString(), static_cast<int>(next.turns), reason);
341: 			return false;
342: 		}
343: 		step = next.coord;
344: 	}
345: 
346: 	// Targets are in visitable coordinates; the request needs the hero's object coordinates.
