424: void CDirectorAI::requestRealized(PackageApplied * pa)
425: {
426: 	if(pa->player != playerID)
427: 		return;
428: 	if(pendingEconomy && static_cast<int>(pa->requestID) == economyRequest)
429: 	{
430: 		pendingEconomy = false;
431: 		logGlobal->info("DirectorAI: economy request finished id=%d success=%d", economyRequest, pa->result);
432: 		traceState(pa->result ? "economy_applied" : "economy_failed");
433: 		advanceTurn();
434: 	}
435: 	auto query = queryRequests.find(pa->requestID);
436: 	if(query != queryRequests.end())
437: 	{
438: 		if(pa->result)
439: 			pendingQueries.erase(query->second);
440: 		queryRequests.erase(query);
441: 		advanceTurn();
442: 	}
443: 	if(pa->packType == CTypeList::getInstance().getTypeID<MoveHero>(nullptr) && pendingMove)
444: 	{
445: 		pendingMove = false;
446: 		traceState(pa->result ? "move_applied" : "move_failed");
447: 		if(!pa->result)
448: 			blockedHeroes.insert(pendingHero.getNum());
449: 		advanceTurn();
450: 	}
451: 	if(pa->packType == CTypeList::getInstance().getTypeID<EndTurn>(nullptr) && endingTurn)
452: 	{
453: 		endingTurn = false;
454: 		if(pa->result)
455: 			turnActive = false;
456: 	}
457: }
